      "Firings.InverseFiredUnit": {
        "table": "Firings",
        "field": "InverseFiredUnit",
        "kind": "formula",
        "rule": "Das Feld „Inverse Fired Unit“ des Firing wird nach folgender Priorität bestimmt:\n1. 1, wenn alles Folgende gilt: das Kennzeichen „Rule Enabled“ gesetzt ist; der Kind „inverse“ ist; und das Kennzeichen „First is in Effect“ gesetzt ist;\n2. andernfalls 0.",
        "mechanical": false,
        "refs": [
          {
            "table": "Firings",
            "field": "RuleEnabled",
            "label": "rule enabled"
          },
          {
            "table": "Firings",
            "field": "Kind",
            "label": "kind"
          },
          {
            "table": "Firings",
            "field": "FirstIsInEffect",
            "label": "first is in effect"
          }
        ],
        "structure": {
          "kind": "priority",
          "headline": "Das Feld „Inverse Fired Unit“ des Firing wird nach folgender Priorität bestimmt:",
          "cases": [
            {
              "value": "1",
              "when": {
                "kind": "all",
                "children": [
                  {
                    "kind": "leaf",
                    "text": "das Kennzeichen „Rule Enabled“ gesetzt ist"
                  },
                  {
                    "kind": "leaf",
                    "text": "der Kind „inverse“ ist"
                  },
                  {
                    "kind": "leaf",
                    "text": "das Kennzeichen „First is in Effect“ gesetzt ist"
                  }
                ]
              }
            },
            {
              "value": "0",
              "when": null
            }
          ],
          "children": null
        },
        "plain": "Wenn Rule Enabled, Kind ist \"inverse\", und First is in Effect, dann 1, andernfalls 0"
      },
